/**
 *
 * ToastMessage groups the title, description and action text content within a Toast.
 *
 * [Live Demo](https://www.primereact.org/toast/)
 *
 * @module ToastMessage
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { ToastRootInstance } from './ToastRoot.types';
/**
 * Defines passthrough(pt) options type in ToastMessage component.
 */
export type ToastMessagePassThroughType<E> = PassThroughType<ToastMessageInstance, E>;
/**
 * Defines passthrough(pt) options of ToastMessage component.
 */
export interface ToastMessagePassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: ToastMessagePassThroughType<React.HTMLAttributes<HTMLDivElement>>;
}
/**
 * Defines valid properties in ToastMessage component.
 */
export interface ToastMessageProps extends BaseComponentProps<ToastMessageInstance, unknown, ToastMessagePassThrough> {
}
/**
 * Defines valid state in ToastMessage component.
 */
export interface ToastMessageState {
}
/**
 * Defines the methods and properties exposed by ToastMessage component.
 */
export interface ToastMessageExposes {
    /**
     * The Toast component instance.
     */
    toast: ToastRootInstance | undefined | null;
}
/**
 * Instance of ToastMessage component.
 */
export type ToastMessageInstance = ComponentInstance<ToastMessageProps, ToastMessageState, ToastMessageExposes>;
